232	// ---------------------------------------------------------------------------
233	// Preflight helpers
234	// ---------------------------------------------------------------------------
235	
236	/**
237	 * Resolves the `orchestrate` binary path within the orchestrator venv.
238	 * Uses `Scripts/orchestrate.exe` on Windows, `bin/orchestrate` elsewhere.
239	 */
240	function resolveOrchestrateBin(workspaceRoot: string): string {
241	  const subdir = process.platform === 'win32' ? 'Scripts' : 'bin';
242	  const ext    = process.platform === 'win32' ? '.exe'    : '';
243	  return join(workspaceRoot, 'orchestrator', '.venv', subdir, `orchestrate${ext}`);
244	}
245	
246	/**
247	 * Validates the plan folder basename matches `YYYY-MM-DD-{project-name}`.
248	 * Wraps planFolderBasename() so any thrown error becomes a failed check.
249	 */

250	function checkPlanBasename(resolvedPlan: string): PreflightResult {
251	  try {
252	    planFolderBasename(dirname(resolvedPlan));
253	    return { name: 'plan-basename', pass: true, detail: 'Plan folder follows naming convention' };
254	  } catch {
255	    return {
256	      name:   'plan-basename',
257	      pass:   false,
258	      detail: 'Plan path does not follow naming convention',
259	      fix:    'The plan folder must match YYYY-MM-DD-{project-name} (e.g. 2026-05-05-my-feature)',
260	    };
261	  }
262	}
