264	/** Checks that the plan file exists on disk. */
265	async function checkPlanFile(resolvedPlan: string): Promise<PreflightResult> {
266	  try {
267	    await stat(resolvedPlan);
268	    return {
269	      name:   'plan-file',
270	      pass:   true,
271	      detail: `Plan file found: ${basename(resolvedPlan)}`,
272	    };
273	  } catch {
274	    return {
275	      name:   'plan-file',
276	      pass:   false,
277	      detail: `Plan file not found: ${resolvedPlan}`,
278	    };
279	  }
