282	/** Checks that the orchestrator venv exists and contains the `orchestrate` binary. */
283	async function checkVenv(workspaceRoot: string): Promise<PreflightResult> {
284	  const venvDir = join(workspaceRoot, 'orchestrator', '.venv');
285	  try {
286	    await stat(venvDir);
287	  } catch {
288	    return {
289	      name:   'venv',
290	      pass:   false,
291	      detail: '.venv directory not found',
292	      fix:    'node scripts/cli.js setup --components orchestrator',
293	    };
294	  }
295	
296	  const binPath = resolveOrchestrateBin(workspaceRoot);
297	  try {
298	    await stat(binPath);
299	  } catch {
300	    return {
301	      name:   'venv',
302	      pass:   false,
303	      detail: 'orchestrate binary not found in .venv',
304	      fix:    'node scripts/cli.js setup --components orchestrator --force',
305	    };
